    "Show all ANRs": {"res": "Settings:show_all_anrs", "hu": "Összes ANR mutatása", "de": "Alle ANRS anzeigen", "fr": "Afficher tous les messages \"L'application ne répond pas\"", "es": "Errores sin respuesta"},
    "Show App Not Responding dialog for background apps": {"res": "Settings:show_all_anrs_summary", "hu": "Az Alkalmazás nem válaszol ablak megjelenítése", "de": "Dialogfeld \"App antwortet nicht\" für Hintergrund-Apps anzeigen", "fr": "Afficher \"L'application ne répond plus\" pour applis en arrière-plan", "es": "Mostrar error de que la aplicación no responde para aplicaciones en segundo plano"},
    "Type your current full backup password here": {"res": "Settings:current_backup_pw_prompt", "hu": "Adja meg a jelenlegi, teljes biztonsági mentéshez használt jelszavát", "de": "Geben Sie Ihr aktuelles Passwort für vollständige Sicherungen hier ein.", "fr": "Saisissez le mot de passe actuel utilisé pour les sauvegardes complètes.", "es": "Introduce aquí la contraseña actual de copia de seguridad completa"},
    "Type a new password for full backups here": {"res": "Settings:new_backup_pw_prompt", "hu": "Írjon be új jelszót a teljes mentésekhez itt", "de": "Geben Sie hier ein neues Passwort für vollständige Sicherungen ein.", "fr": "Saisissez votre nouveau mot de passe pour les sauvegardes complètes.", "es": "Introduce una contraseña nueva para copias de seguridad completas."},
    "Retype your new full backup password here": {"res": "Settings:confirm_new_backup_pw_prompt", "hu": "Még egyszer írja be a teljes mentés új jelszavát", "de": "Geben Sie Ihr neues Passwort für vollständige Sicherungen hier erneut ein.", "fr": "Confirmez ici votre nouveau mot de passe de sauvegarde complète.", "es": "Vuelve a escribir aquí la nueva contraseña de copia de seguridad completa"},
